from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_colors = [grid[r][0] for r in range(h) if all(v == grid[r][0] for v in grid[r])]
    col_colors = [grid[0][c] for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    candidates = Counter(row_colors + col_colors)
    if not candidates:
        return [row[:] for row in grid]
    background = candidates.most_common(1)[0][0]
    separator_rows = {r for r in range(h) if all(v == background for v in grid[r])}
    separator_cols = {c for c in range(w) if all(grid[r][c] == background for r in range(h))}
    return [[2 if grid[r][c] == background and (r in separator_rows or c in separator_cols) else grid[r][c]
             for c in range(w)] for r in range(h)]
